  "geracao_sequencia_aleatoria": {"julgamento": "Low", "justificativa": "O artigo descreve o uso de uma lista gerada por computador com blocos de tamanhos variados (quatro e seis) para a alocação 1:1."},
  "ocultacao_alocacao": {"julgamento": "Low", "justificativa": "As alocações foram seladas em envelopes opacos por um investigador não envolvido no estudo, garantindo a ocultação até o dia da cirurgia."},
  "cegamento_participantes_equipe": {"julgamento": "High", "justificativa": "Os autores reconhecem explicitamente que o cegamento dos anestesiologistas responsáveis pela gestão dos pacientes foi impossível devido à natureza da intervenção."},
  "cegamento_avaliadores_desfecho": {"julgamento": "Low", "justificativa": "Os investigadores que avaliaram os desfechos pós-operatórios e os cirurgiões estavam cegos à alocação dos grupos."},
  "dados_desfecho_incompletos": {"julgamento": "Low", "justificativa": "O fluxo do estudo (Fig. 2) reporta todas as exclusões e desistências, e os autores indicam que 75 dos 82 pacientes incluídos compõem a análise final, explicando as perdas."},
  "relato_seletivo": {"julgamento": "Low", "justificativa": "O estudo foi registrado antes da inclusão dos participantes (NCT03505112), o que mitigou o risco de relato seletivo de desfechos."},
  "outros_vieses": {"julgamento": "Low", "justificativa": "Os autores discutem limitações como o tamanho amostral e a heterogeneidade, mas não apontam evidências de interferência externa ou conflitos de interesses que comprometam a integridade do processo."},
  "risco_global": {"julgamento": "Low", "justificativa": "Apesar do alto risco de viés no cegamento da equipe, o estudo é um ensaio randomizado e registrado, com ocultação de alocação e cegamento dos avaliadores preservados, resultando em um risco global baixo."}
